@push('scripts')<script>
function checkoutForm(totals,coupon,zone,payment){return{totals,coupon,zone,payment,ready:false,loading:false,submitting:false,error:'',request:0,money(v){return '৳'+(v/100).toLocaleString('en-BD',{minimumFractionDigits:2,maximumFractionDigits:2})},async refresh(){const sequence=++this.request;this.ready=false;this.loading=true;this.error='';try{const response=await fetch(@json(route('checkout.quote')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name=csrf-token]').content},body:JSON.stringify({delivery_zone_id:this.zone||null,coupon:this.coupon})});const data=await response.json();if(sequence!==this.request)return;if(!response.ok)throw new Error(Object.values(data.errors||{}).flat()[0]||'হিসাব করা যায়নি। আবার চেষ্টা করুন।');this.totals=data;this.ready=!!this.zone}catch(e){if(sequence===this.request)this.error=e.message}finally{if(sequence===this.request)this.loading=false}}}}
</script>@endpush
